func COMObjectIIDFromString(lpsz string) *win32.GUID {
	var buffer []uint16 = utf16.Encode([]rune((fmt.Sprintf("%s\u0000", lpsz))))
	var lpiid *win32.GUID = win32.NewGUID()
	if win32.COMIIDFromString(buffer, lpiid) == win32.COMS_OK {
		return lpiid
	}
	return nil
}

